Use a circular buffer with a separate element count so all 17 slots are usable, overflow is rejected without changing the queue, and pushes and pops take constant time. Advancing the head and tail modulo 17 preserves FIFO order while reusing freed slots. Compile with C++17 and without defining NDEBUG so the test assertions run: `g++ -std=c++17 -Wall -Wextra -pedantic fifo.cpp -o fifo && ./fifo`.

```cpp
#include <array>
#include <cassert>
#include <cstddef>

class BoundedFIFO {
public:
    static constexpr std::size_t capacity = 17;

    bool push(int value) {
        if (count_ == capacity) {
            return false;
        }
        data_[tail_] = value;
        tail_ = (tail_ + 1) % capacity;
        ++count_;
        return true;
    }

    bool pop(int& value) {
        if (count_ == 0) {
            return false;
        }
        value = data_[head_];
        head_ = (head_ + 1) % capacity;
        --count_;
        return true;
    }

private:
    std::array<int, capacity> data_{};
    std::size_t head_ = 0;
    std::size_t tail_ = 0;
    std::size_t count_ = 0;
};

int main() {
    BoundedFIFO queue;
    int value = -1;

    assert(!queue.pop(value));
    assert(value == -1);

    for (int i = 0; i < 17; ++i) {
        assert(queue.push(i));
    }
    assert(!queue.push(999));
    for (int i = 0; i < 17; ++i) {
        assert(queue.pop(value));
        assert(value == i);
    }
    assert(!queue.pop(value));

    // Keep items queued while both indices wrap around.
    for (int i = 100; i < 117; ++i) {
        assert(queue.push(i));
    }
    for (int i = 100; i < 110; ++i) {
        assert(queue.pop(value));
        assert(value == i);
    }
    for (int i = 117; i < 127; ++i) {
        assert(queue.push(i));
    }
    assert(!queue.push(999));
    for (int i = 110; i < 127; ++i) {
        assert(queue.pop(value));
        assert(value == i);
    }
    assert(!queue.pop(value));
}
